proc contractEventIndex*(name: string): int =
  ## Index into the tables above, -1 for a custom event. A `case` over string
  ## literals: no allocation, no table to share between threads.
  case name
  of evInit: 0
  of evRender: 1
  of evOpen: 2
  of evClose: 3
  of evKeyDown: 4
  of evKeyUp: 5
  of evTextInput: 6
  of evPointerMove: 7
  of evPointerDown: 8
  of evPointerUp: 9
  of evPointerCancel: 10
  of evMouseMove: 11
  of evMouseDown: 12
  of evMouseUp: 13
  of evTap: 14
  of evDoubleTap: 15
  of evLongPress: 16
  of evSwipe: 17
  of evWheel: 18
  of evTurnOn: 19
  of evTurnOff: 20
  of evButton: 21
  of evSetSceneState: 22
  of evSetCurrentScene: 23
  of evMetrics: 24
  of evReload: 25
  of evRestart: 26
  of evReboot: 27
  of evUploadScenes: 28
  else: -1

proc eventAliasCount*(name: string): int =
  ## How many old names a listener may know `name` by (eventAlias).
  case name
  of evPointerMove: 1
  of evPointerDown: 1
  of evPointerUp: 1
  else: 0

proc eventAlias*(name: string, index: int): string =
  ## The old names of `name`, in order; the dispatcher delivers each one too,
  ## with that alias's own (smaller) payload. Empty past eventAliasCount.
  case name
  of evPointerMove:
    case index
    of 0: evMouseMove
    else: ""
  of evPointerDown:
    case index
    of 0: evMouseDown
    else: ""
  of evPointerUp:
    case index
    of 0: evMouseUp
    else: ""
  else: ""

proc eventPayloadKeyCount*(name: string): int =
  ## How many payload fields the contract lists for `name` (0 for a custom event).
  case name
  of evOpen: 1
  of evKeyDown: 8
  of evKeyUp: 7
  of evTextInput: 1
  of evPointerMove: 5
  of evPointerDown: 6
  of evPointerUp: 6
  of evPointerCancel: 4
  of evMouseMove: 2
  of evMouseDown: 1
  of evMouseUp: 1
  of evTap: 4
  of evDoubleTap: 4
  of evLongPress: 5
  of evSwipe: 7
  of evWheel: 4
  of evButton: 7
  of evSetSceneState: 2
  of evSetCurrentScene: 2
  of evUploadScenes: 3
  else: 0

proc eventPayloadKey*(name: string, index: int): string =
  ## The contract's payload fields of `name`, in order. Empty past the count.
  case name
  of evOpen:
    case index
    of 0: "sceneId"
    else: ""
  of evKeyDown:
    case index
    of 0: "code"
    of 1: "key"
    of 2: "repeat"
    of 3: "shift"
    of 4: "ctrl"
    of 5: "alt"
    of 6: "meta"
    of 7: "linuxCode"
    else: ""
  of evKeyUp:
    case index
    of 0: "code"
    of 1: "key"
    of 2: "shift"
    of 3: "ctrl"
    of 4: "alt"
    of 5: "meta"
    of 6: "linuxCode"
    else: ""
  of evTextInput:
    case index
    of 0: "text"
    else: ""
  of evPointerMove:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "pointerId"
    of 3: "pointerType"
    of 4: "buttons"
    else: ""
  of evPointerDown:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "button"
    of 3: "buttons"
    of 4: "pointerId"
    of 5: "pointerType"
    else: ""
  of evPointerUp:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "button"
    of 3: "buttons"
    of 4: "pointerId"
    of 5: "pointerType"
    else: ""
  of evPointerCancel:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "pointerId"
    of 3: "pointerType"
    else: ""
  of evMouseMove:
    case index
    of 0: "x"
    of 1: "y"
    else: ""
  of evMouseDown:
    case index
    of 0: "button"
    else: ""
  of evMouseUp:
    case index
    of 0: "button"
    else: ""
  of evTap:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "pointerId"
    of 3: "pointerType"
    else: ""
  of evDoubleTap:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "pointerId"
    of 3: "pointerType"
    else: ""
  of evLongPress:
    case index
    of 0: "x"
    of 1: "y"
    of 2: "durationMs"
    of 3: "pointerId"
    of 4: "pointerType"
    else: ""
  of evSwipe:
    case index
    of 0: "direction"
    of 1: "x"
    of 2: "y"
    of 3: "startX"
    of 4: "startY"
    of 5: "pointerId"
    of 6: "pointerType"
    else: ""
  of evWheel:
    case index
    of 0: "deltaX"
    of 1: "deltaY"
    of 2: "x"
    of 3: "y"
    else: ""
  of evButton:
    case index
    of 0: "pin"
    of 1: "label"
    of 2: "role"
    of 3: "action"
    of 4: "durationMs"
    of 5: "wake"
    of 6: "level"
    else: ""
  of evSetSceneState:
    case index
    of 0: "state"
    of 1: "render"
    else: ""
  of evSetCurrentScene:
    case index
    of 0: "sceneId"
    of 1: "state"
    else: ""
  of evUploadScenes:
    case index
    of 0: "scenes"
    of 1: "sceneId"
    of 2: "state"
    else: ""
  else: ""

proc eventListenDefault*(name: string): (string, string) =
  ## The one payload field of `name` with a `listenDefault`, and the value: a
  ## listener with no filter on that field hears only events where it equals
  ## this (`button` without an `action` filter hears presses). ("", ""): none.
  case name
  of evButton: ("action", "press")
  else: ("", "")

proc buttonRoleForLabel*(upperLabel: string): string =
  ## The default role of a GPIO button that has none configured, by its label
  ## (upper-cased by the caller); empty when the label says nothing.
  case upperLabel
  of "A": "primary"
  of "B": "next"
  of "C": "prev"
  of "D": "back"
  of "BOOT": "primary"
  of "KEY1": "next"
  of "KEY2": "prev"
  of "KEY3": "next"
  of "BUTTON": "primary"
  of "POWER": "primary"
  of "OK": "primary"
  of "ENTER": "primary"
  of "SELECT": "primary"
  of "HOME": "menu"
  of "MENU": "menu"
  of "EXIT": "back"
  of "BACK": "back"
  of "NEXT": "next"
  of "RIGHT": "next"
  of "PREV": "prev"
  of "LEFT": "prev"
  of "UP": "up"
  of "DOWN": "down"
  of "REFRESH": "refresh"
  else: ""
